static void interruptAndAwait(Thread t, long timeoutMs) throws InterruptedException {
    t.interrupt();
    t.join(timeoutMs);
    if (t.isAlive()) System.out.println("watek NIE zareagowal na interrupt w czasie");
    else System.out.println("watek zakonczyl sie poprawnie");
}
