static boolean respondsToInterrupt(Runnable task, long maxWaitMs) throws InterruptedException {
    Thread t = new Thread(task);
    t.start();
    Thread.sleep(50);
    t.interrupt();
    t.join(maxWaitMs);
    return !t.isAlive();
}
