static void shutdownGracefully(ExecutorService pool, long timeoutMs) throws InterruptedException {
    pool.shutdown();
    if (!pool.awaitTermination(timeoutMs, TimeUnit.MILLISECONDS)) {
        System.out.println("timeout - wysylam interrupt przez shutdownNow()");
        pool.shutdownNow();
        pool.awaitTermination(2, TimeUnit.SECONDS);
    }
}
