class InterruptResponsivenessTracker {
    static long measure(Runnable task) throws InterruptedException {
        Thread t = new Thread(task);
        t.start();
        Thread.sleep(50);
        long start = System.nanoTime();
        t.interrupt();
        t.join(2000);
        return (System.nanoTime()-start)/1_000_000;
    }
}
