static <T> Optional<T> computeWithTimeout(Supplier<T> computation, long timeoutMs) throws InterruptedException {
    AtomicReference<T> wynik = new AtomicReference<>();
    Thread t = new Thread(() -> { T w = computation.get(); wynik.set(w); });
    t.start();
    t.join(timeoutMs);
    if (t.isAlive()) { t.interrupt(); return Optional.empty(); }
    return Optional.ofNullable(wynik.get());
}
