static List<Thread> interruptAllAndFindStuck(List<Thread> watki, long timeoutMs) throws InterruptedException {
    for (Thread t : watki) t.interrupt();
    for (Thread t : watki) t.join(timeoutMs);
    List<Thread> utkniete = new ArrayList<>();
    for (Thread t : watki) if (t.isAlive()) utkniete.add(t);
    return utkniete;
}
