for (int i=0;i<4;i++) pool.submit(() -> { try { while (!Thread.currentThread().isInterrupted()) { Integer z = zadania.poll(200, TimeUnit.MILLISECONDS); if (z != null) przetworzone.incrementAndGet(); } } catch (InterruptedException e) { Thread.currentThread().interrupt(); } });
Thread.sleep(1000);
genFuture.cancel(false);
generator.shutdown(); generator.awaitTermination(2, TimeUnit.SECONDS);
pool.shutdown();
if (!pool.awaitTermination(1, TimeUnit.SECONDS)) pool.shutdownNow();
